insert into public.letter_drafts (id, data) values ('first-letter', '{"id": "first-letter", "issue": 1, "date": "2026-11-08", "title": "쉬운 게\n하나도 없다.", "subtitle": "낯선 땅에서 배우는 기다림,\n그 모든 순간에 함께하시는 하나님.", "cover": "/assets/photos/0195618fbdef.jpg", "sidePhoto": "/assets/photos/213b1f1bc11f.jpg", "intro": "<p>안녕하세요.<br>저희 가정의 선교를 응원해 주시고 후원해 주시는 동역자 여러분, 분주한 시간들이 지나고 드디어 첫 번째 기도편지를 전합니다.</p><p>정착하는 과정에서 있었던 일들, 내면의 고민과 영적 씨름들, 그리고 3주간 하나님의 손길의 흔적들을 짧게 나눠 보려고 합니다.</p>", "quote": "쉬운 게 하나도 없습니다. 그래서 좋습니다.\n왜냐하면 기도할 수 있기 때문입니다.", "sections": [{"title": "만남의 복", "html": "<p>10월 13일 아침, 드디어 꿈꾸던 선교지 코트디부아르 아비장(Abidjan)에 도착했습니다.</p><p>비행기에서 내리자 뜨거운 바람과 쩍쩍 달라붙는 습도가 저희 가족을 맞았습니다. 여기저기서 들리는 낯선 언어, 익숙하지 않은 모든 상황. 혹여 짐을 빼앗기지는 않을까 긴장하며 공항에 들어섰습니다.</p><p>감사하게도 저희는 아무 문제 없이 무사히 공항을 통과했고, 아비장 한인교회 장로님과 권사님께서 저희를 반갑게 맞아 주셨습니다. 이곳 한인분들 이야기로는 외국인이 이렇게 많은 짐을 가지고 순탄하게 들어오는 경우는 드물며 하나님의 은혜라고 했습니다. 저희는 코트디 입성 첫걸음부터 하나님의 보호하심과 중보기도의 힘 을 느낄 수 있었습니다.</p><p>어느새 3주가 지났습니다. 돌아보니 하나님은 저희 곁에 좋은 분들을 먼저 예비해 두셨습니다. 한인 교민분들, 그리고 다른 단체의 선교사님들. 이분들의 도움이 없었다면 혼자서는 결코 해낼 수 없었을 일들을 하나씩 해 나가고 있습니다.</p><p>이 시간들을 마음 깊이 새깁니다. 시간이 흘러 이곳 생활에 익숙해지더라도 교만하지 않고 늘 겸손하겠다고 다짐해 봅니다.</p><p>저희 가정이 항상 겸손할 수 있도록, 그리고 하나님이 주시는 만남의 복이 끊이지 않도록 함께 기도해 주세요.</p>", "photos": []}, {"title": "다시, 기도", "html": "<p>한 달이 다 되어 갑니다.</p><p>집 · 거주증 · 현지 운전면허증 · 은행 어카운트 · 모바일 (Orange, Wave) 어카운트 · 핸드폰 개통 · 생활용품, 가전제품, 가구 구입 · 아이들 학교입학 · 언어(불어) 학교 신청</p><p>정착을 위해 해야 할 일들입니다. 보통 2~3달 정도 걸린다고 합니다.</p><p>이 일들을 해 나가는데 생각대로 쉽게 되지가 않습니다.</p><p>은행 어카운트를 만들려고 은행을 몇 번이나 방문했는지 모릅니다. 어느 날은 아무것도 못하고 그냥 돌아온 적도 있습니다. 지금도 진행 중입니다.</p><p>한국에서는 일주일이면 가능할지 몰라도, 아프리카에서는 인내와 기다림이 필요합니다.</p><p>그리고 ''기도'' 가 필요합니다.</p><p>쉬운 게 하나도 없습니다. 그래서 좋습니다. 왜냐하면 기도할 수 있기 때문 입니다.</p><p>참 아이러니하게, 이러한 상황이 스트레스이고, 분명 힘듦이 있지만, 이 시간을 통해 하나님 앞에 간절하게 기도할 수 있어서 좋습니다. 아이들도 함께 기도합니다. 정착하는 데 위의 일들이 잘 해결될 수 있도록 기도해 주시고, 선교의 여정 속에서 저희 가정이 항상 깨어 기도할 수 있도록 중보해 주십시오.</p>", "photos": []}, {"title": "미움과 사랑 그 사이 어딘가", "html": "<p>출국 전, 저는 코트디부아르의 영혼들을 상상하며 기도했습니다.</p><p>\"하나님, 그들을 향한 주님의 사랑이 제게도 부어지게 하소서.\"</p><p>그런데 막상 마주한 현실은 달랐습니다.</p><p>이곳 사람들의 눈에 우리는 돈을 얻어낼 수 있는 이방인처럼 보이는 듯했습니다.</p><p>도움을 주면 당연하게 여겼고, 무언가 얻어낼 것이 없는지 살피는 눈빛도 느껴졌습니다.</p><p>길에서는 경찰이 아무 이유 없이 저를 세웠고, 몇 번이나 돈을 요구했습니다.</p><p>반갑게 인사하며 마음을 나눴다고 생각한 경비원도 아파트 키를 하나 더 만들라며 터무니없는 가격을 말했습니다.</p><p>몇 번 겪고 나니, 저도 모르게 허탈한 웃음이 났습니다.</p><p>''이 일을 나는 어떻게 받아들여야 할까.'' 생각이 깊어졌습니다.</p><p>그러다 예수님이 떠올랐습니다.</p><p>예수님도 우리를 도우러 오셨지만, 우리는 그분을 이해하지 못했습니다.</p><p>그러나 예수님은 끝까지 우리를 포기하지 않으시고 사랑하셨습니다.</p><p>지금은 이들의 삶의 방식과 모습을 있는 그대로 받아들이는 연습 을 하고 있습니다.</p><p>그리고 조금씩 더 이해하고, 더 사랑하려 합니다.</p>", "photos": []}, {"title": "지경을 넓히다", "html": "<p>서울 온누리교회에서 내년 아비장에서 개최할 ''인투 컨퍼런스'' 를 위해 답사차 코트디 를 방문하셨습니다. 목사님들과 함께 아비장의 복음주의 기독교 교단 지도자분들과 만남을 가 졌고, 곳곳의 현지 교회들을 방문할 수 있었습니다.</p><p>내년에 있을 인투 컨퍼런스를 통해 코트디부아르 목사님들과 서로 소통하고 배우며 특별히, 코트디부아르에 선교하는 교회 가 일어나길 소망합니다.</p><p>6권역 아프리카 전략회의 가 이스탄불에서 있었습니다. 감사하게도 저희 가정도 참여할 수 있는 기회가 주어졌습니다. 아프리카 여러 지역의 선교사님들과 교제의 시간을 가졌고, 특히 선교사님들의 사역을 듣고 배울 수 있는 시간이어서 좋았습니다.</p>", "photos": []}], "prayers": [{"title": "예비하신 만남과 사명의 길", "body": "하나님이 예비하신 만남의 복을 끊임없이 경험하게 하소서. 하나님의 사람들을 만나고, 인도하시는 길을 따라 사명을 잘 감당하게 하소서."}, {"title": "겸손으로 기도하는 가정", "body": "항상 겸손한 마음으로 기도하는 가정이 되게 하소서. 무더운 날씨와 낯선 문화 속에서도 생각과 마음을 지키고, 하나님의 눈으로 이 땅을 보게 하소서."}, {"title": "언어의 진보", "body": "11월 중순부터 시작하는 불어 수업에서 좋은 선생님을 만나게 하소서. 용기 있게 배우며 실력이 쑥쑥 늘게 하소서."}, {"title": "가족의 현지 적응과 건강", "body": "아이들이 새로 입학하는 학교에 잘 적응하게 하소서. 물갈이와 말라리아, 풍토병으로부터 가족의 건강을 지켜 주시고, 특히 아이들이 물갈이로 배가 아프지 않게 하소서."}], "gallery": [{"url": "/assets/photos/213b1f1bc11f.jpg", "caption": "새로운 시작, 우리 가족"}, {"url": "/assets/photos/5e380c696855.jpg", "caption": "함께 배우는 일상"}, {"url": "/assets/photos/b08934f45aa4.jpg", "caption": "이 땅의 교회를 만나다"}], "youtube": {"url": "https://www.youtube.com/watch?v=Ie07qxjnmGI", "title": "무명", "description": "선교가는 가정을 위해 만들어 준 찬양입니다.\n여러분과 함께 나누고 싶습니다."}}'::jsonb)
insert into public.letters_published (id, data, published_at) values ('first-letter', '{"id": "first-letter", "issue": 1, "date": "2026-11-08", "title": "쉬운 게\n하나도 없다.", "subtitle": "낯선 땅에서 배우는 기다림,\n그 모든 순간에 함께하시는 하나님.", "cover": "/assets/photos/0195618fbdef.jpg", "sidePhoto": "/assets/photos/213b1f1bc11f.jpg", "intro": "<p>안녕하세요.<br>저희 가정의 선교를 응원해 주시고 후원해 주시는 동역자 여러분, 분주한 시간들이 지나고 드디어 첫 번째 기도편지를 전합니다.</p><p>정착하는 과정에서 있었던 일들, 내면의 고민과 영적 씨름들, 그리고 3주간 하나님의 손길의 흔적들을 짧게 나눠 보려고 합니다.</p>", "quote": "쉬운 게 하나도 없습니다. 그래서 좋습니다.\n왜냐하면 기도할 수 있기 때문입니다.", "sections": [{"title": "만남의 복", "html": "<p>10월 13일 아침, 드디어 꿈꾸던 선교지 코트디부아르 아비장(Abidjan)에 도착했습니다.</p><p>비행기에서 내리자 뜨거운 바람과 쩍쩍 달라붙는 습도가 저희 가족을 맞았습니다. 여기저기서 들리는 낯선 언어, 익숙하지 않은 모든 상황. 혹여 짐을 빼앗기지는 않을까 긴장하며 공항에 들어섰습니다.</p><p>감사하게도 저희는 아무 문제 없이 무사히 공항을 통과했고, 아비장 한인교회 장로님과 권사님께서 저희를 반갑게 맞아 주셨습니다. 이곳 한인분들 이야기로는 외국인이 이렇게 많은 짐을 가지고 순탄하게 들어오는 경우는 드물며 하나님의 은혜라고 했습니다. 저희는 코트디 입성 첫걸음부터 하나님의 보호하심과 중보기도의 힘 을 느낄 수 있었습니다.</p><p>어느새 3주가 지났습니다. 돌아보니 하나님은 저희 곁에 좋은 분들을 먼저 예비해 두셨습니다. 한인 교민분들, 그리고 다른 단체의 선교사님들. 이분들의 도움이 없었다면 혼자서는 결코 해낼 수 없었을 일들을 하나씩 해 나가고 있습니다.</p><p>이 시간들을 마음 깊이 새깁니다. 시간이 흘러 이곳 생활에 익숙해지더라도 교만하지 않고 늘 겸손하겠다고 다짐해 봅니다.</p><p>저희 가정이 항상 겸손할 수 있도록, 그리고 하나님이 주시는 만남의 복이 끊이지 않도록 함께 기도해 주세요.</p>", "photos": []}, {"title": "다시, 기도", "html": "<p>한 달이 다 되어 갑니다.</p><p>집 · 거주증 · 현지 운전면허증 · 은행 어카운트 · 모바일 (Orange, Wave) 어카운트 · 핸드폰 개통 · 생활용품, 가전제품, 가구 구입 · 아이들 학교입학 · 언어(불어) 학교 신청</p><p>정착을 위해 해야 할 일들입니다. 보통 2~3달 정도 걸린다고 합니다.</p><p>이 일들을 해 나가는데 생각대로 쉽게 되지가 않습니다.</p><p>은행 어카운트를 만들려고 은행을 몇 번이나 방문했는지 모릅니다. 어느 날은 아무것도 못하고 그냥 돌아온 적도 있습니다. 지금도 진행 중입니다.</p><p>한국에서는 일주일이면 가능할지 몰라도, 아프리카에서는 인내와 기다림이 필요합니다.</p><p>그리고 ''기도'' 가 필요합니다.</p><p>쉬운 게 하나도 없습니다. 그래서 좋습니다. 왜냐하면 기도할 수 있기 때문 입니다.</p><p>참 아이러니하게, 이러한 상황이 스트레스이고, 분명 힘듦이 있지만, 이 시간을 통해 하나님 앞에 간절하게 기도할 수 있어서 좋습니다. 아이들도 함께 기도합니다. 정착하는 데 위의 일들이 잘 해결될 수 있도록 기도해 주시고, 선교의 여정 속에서 저희 가정이 항상 깨어 기도할 수 있도록 중보해 주십시오.</p>", "photos": []}, {"title": "미움과 사랑 그 사이 어딘가", "html": "<p>출국 전, 저는 코트디부아르의 영혼들을 상상하며 기도했습니다.</p><p>\"하나님, 그들을 향한 주님의 사랑이 제게도 부어지게 하소서.\"</p><p>그런데 막상 마주한 현실은 달랐습니다.</p><p>이곳 사람들의 눈에 우리는 돈을 얻어낼 수 있는 이방인처럼 보이는 듯했습니다.</p><p>도움을 주면 당연하게 여겼고, 무언가 얻어낼 것이 없는지 살피는 눈빛도 느껴졌습니다.</p><p>길에서는 경찰이 아무 이유 없이 저를 세웠고, 몇 번이나 돈을 요구했습니다.</p><p>반갑게 인사하며 마음을 나눴다고 생각한 경비원도 아파트 키를 하나 더 만들라며 터무니없는 가격을 말했습니다.</p><p>몇 번 겪고 나니, 저도 모르게 허탈한 웃음이 났습니다.</p><p>''이 일을 나는 어떻게 받아들여야 할까.'' 생각이 깊어졌습니다.</p><p>그러다 예수님이 떠올랐습니다.</p><p>예수님도 우리를 도우러 오셨지만, 우리는 그분을 이해하지 못했습니다.</p><p>그러나 예수님은 끝까지 우리를 포기하지 않으시고 사랑하셨습니다.</p><p>지금은 이들의 삶의 방식과 모습을 있는 그대로 받아들이는 연습 을 하고 있습니다.</p><p>그리고 조금씩 더 이해하고, 더 사랑하려 합니다.</p>", "photos": []}, {"title": "지경을 넓히다", "html": "<p>서울 온누리교회에서 내년 아비장에서 개최할 ''인투 컨퍼런스'' 를 위해 답사차 코트디 를 방문하셨습니다. 목사님들과 함께 아비장의 복음주의 기독교 교단 지도자분들과 만남을 가 졌고, 곳곳의 현지 교회들을 방문할 수 있었습니다.</p><p>내년에 있을 인투 컨퍼런스를 통해 코트디부아르 목사님들과 서로 소통하고 배우며 특별히, 코트디부아르에 선교하는 교회 가 일어나길 소망합니다.</p><p>6권역 아프리카 전략회의 가 이스탄불에서 있었습니다. 감사하게도 저희 가정도 참여할 수 있는 기회가 주어졌습니다. 아프리카 여러 지역의 선교사님들과 교제의 시간을 가졌고, 특히 선교사님들의 사역을 듣고 배울 수 있는 시간이어서 좋았습니다.</p>", "photos": []}], "prayers": [{"title": "예비하신 만남과 사명의 길", "body": "하나님이 예비하신 만남의 복을 끊임없이 경험하게 하소서. 하나님의 사람들을 만나고, 인도하시는 길을 따라 사명을 잘 감당하게 하소서."}, {"title": "겸손으로 기도하는 가정", "body": "항상 겸손한 마음으로 기도하는 가정이 되게 하소서. 무더운 날씨와 낯선 문화 속에서도 생각과 마음을 지키고, 하나님의 눈으로 이 땅을 보게 하소서."}, {"title": "언어의 진보", "body": "11월 중순부터 시작하는 불어 수업에서 좋은 선생님을 만나게 하소서. 용기 있게 배우며 실력이 쑥쑥 늘게 하소서."}, {"title": "가족의 현지 적응과 건강", "body": "아이들이 새로 입학하는 학교에 잘 적응하게 하소서. 물갈이와 말라리아, 풍토병으로부터 가족의 건강을 지켜 주시고, 특히 아이들이 물갈이로 배가 아프지 않게 하소서."}], "gallery": [{"url": "/assets/photos/213b1f1bc11f.jpg", "caption": "새로운 시작, 우리 가족"}, {"url": "/assets/photos/5e380c696855.jpg", "caption": "함께 배우는 일상"}, {"url": "/assets/photos/b08934f45aa4.jpg", "caption": "이 땅의 교회를 만나다"}], "youtube": {"url": "https://www.youtube.com/watch?v=Ie07qxjnmGI", "title": "무명", "description": "선교가는 가정을 위해 만들어 준 찬양입니다.\n여러분과 함께 나누고 싶습니다."}}'::jsonb, now())
insert into public.site_settings (key, value) values
  ('featured', '"first-letter"'::jsonb),
  ('order', '["first-letter"]'::jsonb)
